WITH H AS ( SELECT APPLICATION_ID, MIN(CASE WHEN NEW_STATUS_CODE='CREDIT_APPROVED' THEN CAST(CHANGED_AT AS DATE) END) CREDIT_APPROVAL_DATE, MIN(CASE WHEN NEW_STATUS_CODE='DISBURSED' THEN CAST(CHANGED_AT AS DATE) END) DISBURSEMENT_DATE FROM MFF_APPLICATION_STATUS_HIST GROUP BY APPLICATION_ID ) SELECT a.APPLICATION_ID, a.APPLICATION_NO, a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, a.APPLICATION_DATE, h.CREDIT_APPROVAL_DATE, h.DISBURSEMENT_DATE, CASE WHEN h.CREDIT_APPROVAL_DATE IS NOT NULL THEN h.CREDIT_APPROVAL_DATE-a.APPLICATION_DATE END DAYS_TO_CREDIT_APPROVAL, CASE WHEN h.DISBURSEMENT_DATE IS NOT NULL THEN h.DISBURSEMENT_DATE-a.APPLICATION_DATE END DAYS_TO_DISBURSEMENT FROM MFF_APPLICATIONS a JOIN MFF_ORGANIZATIONS o ON o.ORG_ID=a.FINANCIER_ID LEFT JOIN H h ON h.APPLICATION_ID=a.APPLICATION_ID;
